import React, { useState } from "react";

export default function InitiativeSavingsTab() {
  const [form, setForm] = useState({
    // add green inputs here as per Tab3
    input1: "",
    input2: "",
    // computed oranges
    totalPD: 0,
    totalCost: 0,
    savings: 0,
  });

  const onChange = (k, v) => setForm((p) => ({ ...p, [k]: v }));

  // TODO: add useEffect with formulas based on Tab3 orange cells

  return (
    <div className="tab-wrap">
      <div className="tab-section tab-section-yellow">Initiative Savings</div>
      <div className="grid-2">
        <label className="tab-label tab-label-green">Input 1</label>
        <input className="tab-input" type="number" value={form.input1} onChange={(e) => onChange("input1", e.target.value)} />
        <label className="tab-label tab-label-green">Input 2</label>
        <input className="tab-input" type="number" value={form.input2} onChange={(e) => onChange("input2", e.target.value)} />

        <label className="tab-label tab-label-orange">Total PD</label>
        <input className="tab-input tab-input-orange" value={form.totalPD} disabled />
        <label className="tab-label tab-label-orange">Total Cost</label>
        <input className="tab-input tab-input-orange" value={form.totalCost} disabled />
        <label className="tab-label tab-label-orange">Savings</label>
        <input className="tab-input tab-input-orange" value={form.savings} disabled />
      </div>
    </div>
  );
}
